styles.h1:
font-family: "STKaiti", "FangSong", serif;
font-size: 32px;
position: relative;
color: #8b0000; /* 暗红色 */
margin-bottom: 20px;
letter-spacing: 4px;
font-weight: 600;
text-align: center;
padding: 10px 0;
line-height: 1.5;

styles.h2:
font-size: 18px;
color: #5c3317; /* 深棕色 */
margin-bottom: 24px;
font-weight: 400;
letter-spacing: 2px;
text-align: center;
position: relative;
padding-bottom: 15px;
font-family: "STKaiti", "FangSong", serif;

styles.h3:
display: block;
color: #8b0000;
margin-bottom: 6px;
font-size: 17px;
font-weight: 600;

styles.h6:
color: #6b8c42;
margin-top: 1.2em;
margin-bottom: 0.5em;
font-weight: 700;
border-bottom: 1px solid #d4d9c9;
padding-bottom: 0.3em;

styles.a:
color: #8b0000;
text-decoration: none;
border-bottom: 1px solid rgba(165, 42, 42, 0.3);
transition: all 0.3s ease;

styles.ol:
list-style: none;
padding: 0.5em 3.5em;
counter-reset: decorated-counter;
margin-bottom: 1.5em;

styles.li:
position: relative;


margin-bottom: 20px;
padding-left: 40px;
color: #333;
font-size: 16px;
text-align: justify;

styles.blockquote:
background-color: rgba(248, 240, 224, 0.7);
border-left: 4px solid #a52a2a;
color: #5c3317;
padding: 15px 20px;
margin: 20px 0;
font-style: italic;
position: relative;

styles.pre:
border: 1px solid rgba(165, 42, 42, 0.3);
background-color: rgba(248, 240, 224, 0.5);
border-radius: 4px;
padding: 15px;
overflow-x: auto;

styles.hr:
height: 1px;
border: none;
background: repeating-linear-gradient(
  90deg,
  #a52a2a,
  #a52a2a 4px,
  transparent 4px,
  transparent 8px
);
margin: 25px 0;

styles.img:
border: 4px double #a52a2a;
max-width: 100%;
height: auto;
margin: 15px 0;
display: block;
margin-left: auto;
margin-right: auto;

styles.table:
border-collapse: collapse;
margin: 20px 0;
width: 100%;
border: 1px solid #a52a2a;

styles.th:
background-color: rgba(165, 42, 42, 0.1);
color: #8b0000;
padding: 10px;
text-align: center;
border: 1px solid #a52a2a;
font-weight: 600;

styles.td:
color: #333;
padding: 10px;
border: 1px solid rgba(165, 42, 42, 0.3);
text-align: center;
